# Surah At-Tawbah (chapter 9) — part 6: ayat 50-58 (IDs 1285-1293)
SURAH = 9

ENTRIES = {
1285: (
"اگر — تجھے — کوئی بھلائی — پہنچے — ان — کو — تکلیف ہوتی ہے — اور — اگر — تجھے کوئی مصیبت پہنچے — وہ کہتے ہیں — ہم نے — اپنا کام — پہلے ہی سنبھال لیا تھا — اور — منہ موڑ لیتے ہیں — اور — وہ — خوش ہوتے ہیں",
"""۱۔ منافق — مؤمنوں کی بھلائی سے تکلیف پاتے ہیں۔
۲۔ ’’إِن تُصِبْكَ حَسَنَۃٌ تَسُؤْهُمْ وَإِن تُصِبْكَ مُصِيبَۃٌ يَقُولُوا قَدْ أَخَذْنَا أَمْرَنَا مِن قَبْلُ وَيَتَوَلَّوْا وَهُمْ فَرِحُونَ‘‘ — اگر — تجھے — کوئی بھلائی — پہنچے — ان — کو — تکلیف ہوتی ہے — اور — اگر — تجھے کوئی مصیبت پہنچے — وہ کہتے ہیں — ہم نے — اپنا کام — پہلے ہی سنبھال لیا تھا — اور — منہ موڑ لیتے ہیں — اور — وہ — خوش ہوتے ہیں — یعنی منافق — مؤمنوں کی کامیابی کو — اپنی ناکامی سمجھتے ہیں۔
۳۔ عملی سبق: مؤمنوں کی کامیابی — اہلِ ایمان کے لیے خوشی کی بات ہونی چاہیے۔"""
),
1286: (
"کہدو — ہمیں — صرف — وہی — پہنچتا ہے — جو اللہ نے — ہمارے لیے — لکھ رکھا ہے — وہ — ہمارا — کارساز ہے — اور — مؤمنوں کو — اللہ ہی پر — توکل کرنا چاہیے",
"""۱۔ تقدیر — سب کچھ اللہ کے ہاتھ میں ہے۔
۲۔ ’’قُل لَّن يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا هُوَ مَوْلَانَا وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ‘‘ — کہدو — ہمیں — صرف — وہی — پہنچتا ہے — جو اللہ نے — ہمارے لیے — لکھ رکھا ہے — وہ — ہمارا — کارساز ہے — اور — مؤمنوں کو — اللہ ہی پر — توکل کرنا چاہیے — یعنی ہر — خیر و شر — اللہ کی طرف سے لکھی ہوئی چیز ہے؛ توکل — اللہ پر ہی ضروری ہے۔
۳۔ عملی سبق: تقدیر پر ایمان رکھو؛ اللہ پر توکل کرو۔"""
),
1287: (
"کہدو — کیا — تم — ہمارے بارے میں — صرف دو — بھلائیوں — میں سے — ایک — کے منتظر ہو — اور — ہم — تمہارے بارے میں — انتظار کر رہے ہیں — کہ — اللہ — تمہیں — اپنے پاس سے عذاب — میں مبتلا کرے — یا — ہمارے ہاتھوں — پس — انتظار کرو — بے شک — ہم — تمہارے ساتھ — انتظار کر رہے ہیں",
"""۱۔ مؤمنوں کے لیے — دو بھلائیاں — فتح یا شہادت۔
۲۔ ’’قُلْ هَلْ تَرَبَّصُونَ بِنَا إِلَّا إِحْدَى الْحُسْنَيَيْنِ وَنَحْنُ نَتَرَبَّصُ بِكُمْ أَن يُصِيبَكُمُ اللَّهُ بِعَذَابٍ مِّنْ عِندِهِ أَوْ بِأَيْدِينَا فَتَرَبَّصُوا إِنَّا مَعَكُم مُّتَرَبِّصُونَ‘‘ — کہدو — کیا — تم — ہمارے بارے میں — صرف دو — بھلائیوں — میں سے — ایک — کے منتظر ہو — اور — ہم — تمہارے بارے میں — انتظار کر رہے ہیں — کہ — اللہ — تمہیں — اپنے پاس سے عذاب — میں مبتلا کرے — یا — ہمارے ہاتھوں — پس — انتظار کرو — بے شک — ہم — تمہارے ساتھ — انتظار کر رہے ہیں — یعنی مؤمن کے لیے — یا تو فتح ہے — یا شہادت؛ دونوں صورت میں — خوش نصیبی ہے۔
۳۔ عملی سبق: مؤمن — دونوں صورتوں میں — فتح یاب ہے۔"""
),
1288: (
"کہدو — خرچ کرو — خوشی سے یا — مجبوری سے — تم سے — ہرگز — قبول نہ کیا جائے گا — بے شک — تم — فاسق — قوم ہو",
"""۱۔ منافقوں کا — خرچ — کبھی قبول نہیں۔
۲۔ ’’قُلْ أَنفِقُوا طَوْعًا أَوْ كَرْهًا لَّن يُتَقَبَّلَ مِنكُمْ إِنَّكُمْ كُنتُمْ قَوْمًا فَاسِقِينَ‘‘ — کہدو — خرچ کرو — خوشی سے یا — مجبوری سے — تم سے — ہرگز — قبول نہ کیا جائے گا — بے شک — تم — فاسق — قوم ہو — یعنی منافق — نفاق کے ساتھ جو خرچ کرے — وہ — هرگز قبول نہیں۔
۳۔ عملی سبق: خلوص کے بغیر — صدقات — قبول نہیں ہوتے۔"""
),
1289: (
"اور — ان — سے — ان کے نفقات — قبول نہ ہونے کی — کوئی — وجہ — نہیں — مگر — یہ — کہ وہ — اللہ اور اس کے رسولؐ — کا انکار کرتے ہیں — اور — نماز — میں — سستی سے آتے ہیں — اور — خرچ — ناپسند کرتے ہوئے — کرتے ہیں",
"""۱۔ منافق — تین بیماریوں میں مبتلا — کفر، سستی نماز، ناپسندیدگی نفقہ۔
۲۔ ’’وَمَا مَنَعَهُمْ أَن تُقْبَلَ مِنْهُمْ نَفَقَاتُهُمْ إِلَّا أَنَّهُمْ كَفَرُوا بِاللَّهِ وَبِرَسُولِهِ وَلَا يَأْتُونَ الصَّلَاۃَ إِلَّا وَهُمْ كُسَالَىٰ وَلَا يُنفِقُونَ إِلَّا وَهُمْ كَارِهُونَ‘‘ — اور — ان — سے — ان کے نفقات — قبول نہ ہونے کی — کوئی — وجہ — نہیں — مگر — یہ — کہ وہ — اللہ اور اس کے رسولؐ — کا انکار کرتے ہیں — اور — نماز — میں — سستی سے آتے ہیں — اور — خرچ — ناپسند کرتے ہوئے — کرتے ہیں — یعنی منافق — دل سے کافر — نماز کو بوجھ سمجھتے ہیں — اور — خرچ — دباؤ میں کرتے ہیں۔
۳۔ عملی سبق: نماز اور خرچ — خوشی اور اخلاص — سے — کرو۔"""
),
1290: (
"پس — ان — کے مال اور ان کی اولاد — تجھے — تعجب میں نہ ڈالیں — بے شک — اللہ — چاہتا ہے — انہیں — اس — سے عذاب دے — دنیا کی زندگی میں — اور — ان کے — جان — ختم ہو جائیں — وہ — کافر — ہوں",
"""۱۔ منافقوں کی دولت — عارضی — اور آفتیں۔
۲۔ ’’فَلَا تُعْجِبْكَ أَمْوَالُهُمْ وَلَا أَوْلَادُهُمْ إِنَّمَا يُرِيدُ اللَّهُ لِيُعَذِّبَهُم بِهَا فِي الْحَيَاۃِ الدُّنْيَا وَتَزْهَقَ أَنفُسُهُمْ وَهُمْ كَافِرُونَ‘‘ — پس — ان — کے مال اور ان کی اولاد — تجھے — تعجب میں نہ ڈالیں — بے شک — اللہ — چاہتا ہے — انہیں — اس — سے عذاب دے — دنیا کی زندگی میں — اور — ان کے — جان — ختم ہو جائیں — وہ — کافر — ہوں — یعنی منافقوں کی دولت — دنیا میں بھی — ان کے لیے — عذاب کی وجہ بن سکتی ہے۔
۳۔ عملی سبق: دنیاوی دولت — نہ دھوکہ — نہ کامیابی — ہے۔"""
),
1291: (
"اور وہ — اللہ کی — قسم — کھاتے ہیں کہ — وہ — تمہارے ہی — میں سے ہیں — حالانکہ — وہ — تمہارے میں — سے نہیں — لیکن — وہ — ڈرپوک — قسم ہیں — قوم ہیں",
"""۱۔ منافق — اللہ کی قسمیں کھاتے ہیں — مگر وہ تمہارے میں سے نہیں۔
۲۔ ’’وَيَحْلِفُونَ بِاللَّهِ إِنَّهُمْ لَمِنكُمْ وَمَا هُم مِّنكُمْ وَلَٰكِنَّهُمْ قَوْمٌ يَفْرَقُونَ‘‘ — اور وہ — اللہ کی — قسم — کھاتے ہیں کہ — وہ — تمہارے ہی — میں سے ہیں — حالانکہ — وہ — تمہارے میں — سے نہیں — لیکن — وہ — ڈرپوک — قسم ہیں — قوم ہیں — یعنی منافق — اپنی جان بچانے — کے لیے — جھوٹ — قسمیں — کھاتے ہیں۔
۳۔ عملی سبق: منافق کی قسمیں — اس کا نفاق ظاہر کرتی ہیں۔"""
),
1292: (
"اگر — وہ — کوئی پناہ گاہ — یا — غار — یا — کوئی گھس — جانے کی جگہ — پاتے — تو — اس — کی طرف — بھاگیں — اور — وہ — بھاگ جاتے — ہوئے — جلدی کریں",
"""۱۔ منافق — جنگ سے — بھاگنے کے — ہر موقع — کے منتظر۔
۲۔ ’’لَوْ يَجِدُونَ مَلْجَأً أَوْ مَغَارَاتٍ أَوْ مُدَّخَلًا لَّوَلَّوْا إِلَيْهِ وَهُمْ يَجْمَحُونَ‘‘ — اگر — وہ — کوئی پناہ گاہ — یا — غار — یا — کوئی گھس — جانے کی جگہ — پاتے — تو — اس — کی طرف — بھاگیں — اور — وہ — بھاگ جاتے — ہوئے — جلدی کریں — یعنی منافق — جنگ سے — بچنے کے لیے — ہر — پناہ گاہ — تلاش کرتا ہے۔
۳۔ عملی سبق: دشواریاں — ایمان کی جانچ — ہیں۔"""
),
1293: (
"اور ان میں — کوئی — صدقات — کے بارے میں — آپؐ — کو — عیب لگاتا ہے — پس — اگر — انہیں — اس میں سے — دیا جائے — تو وہ — راضی ہوتے ہیں — اور — اگر — انہیں — اس میں سے — نہ دیا جائے — تو — اسی وقت — ناراض ہو جاتے ہیں",
"""۱۔ منافق — صدقات کی — تقسیم پر — بھی — ناراض ہوتے ہیں۔
۲۔ ’’وَمِنْهُم مَّن يَلْمِزُكَ فِي الصَّدَقَاتِ فَإِنْ أُعْطُوا مِنْهَا رَضُوا وَإِن لَّمْ يُعْطَوْا مِنْهَا إِذَا هُمْ يَسْخَطُونَ‘‘ — اور ان میں — کوئی — صدقات — کے بارے میں — آپؐ — کو — عیب لگاتا ہے — پس — اگر — انہیں — اس میں سے — دیا جائے — تو وہ — راضی ہوتے ہیں — اور — اگر — انہیں — اس میں سے — نہ دیا جائے — تو — اسی وقت — ناراض ہو جاتے ہیں — یعنی منافق — مال کے لالچ میں — نبیؐ کو — عیب لگاتے ہیں — اگر — انہیں — صدقہ مل جائے تو — پھر — خوش ہوتے ہیں۔
۳۔ عملی سبق: لالچ — نفاق کی علامت ہے؛ اخلاص — نبیؐ کی تقلید کی بنیاد ہے۔"""
),
}
